{
  "mechanisms": [
    {
      "name": "mb_mf_mixture",
      "title": "MB/MF Mixture Weight",
      "description": "Weights the contribution of model-based and model-free values to stage-1 choices.",
      "params": [
        {
          "name": "w",
          "bounds": [
            0,
            1
          ]
        }
      ],
      "evidence": "q_net = w * q_stage1_mb + (1 - w) * q_stage1_mf",
      "expressible_in_slots": true
    },
    {
      "name": "eligibility_trace",
      "title": "Eligibility Trace",
      "description": "Updates stage-1 model-free values using the stage-2 reward prediction error.",
      "params": [
        {
          "name": "lmbda",
          "bounds": [
            0,
            1
          ]
        }
      ],
      "evidence": "q_stage1_mf[action_1[trial]] += alpha * delta_stage1 + alpha * lmbda * delta_stage2",
      "expressible_in_slots": true
    },
    {
      "name": "counterfactual_updating",
      "title": "Counterfactual Updating",
      "description": "Updates the value of the unchosen stage-2 action in the visited state assuming it would have yielded the opposite reward.",
      "params": [
        {
          "name": "alpha_cf",
          "bounds": [
            0,
            1
          ]
        }
      ],
      "evidence": "unchosen_2 = 1 - action_2[trial]\ncf_reward = 1 - reward[trial]\ndelta_cf = cf_reward - q_stage2_mf[state_idx, unchosen_2]\nq_stage2_mf[state_idx, unchosen_2] += alpha_cf * delta_cf",
      "expressible_in_slots": true
    },
    {
      "name": "value_decay",
      "title": "Value Decay",
      "description": "Decays the model-free values of unchosen stage-1 actions and unvisited stage-2 states towards zero.",
      "params": [
        {
          "name": "decay",
          "bounds": [
            0,
            1
          ]
        }
      ],
      "evidence": "unchosen_1 = 1 - action_1[trial]\nq_stage1_mf[unchosen_1] *= (1 - decay)\n\nfor s in range(2):\n    for a in range(2):\n        if s != state_idx:\n            q_stage2_mf[s, a] *= (1 - decay)",
      "expressible_in_slots": true
    }
  ]
}
